def load_ambient_cfg() -> dict:
    """Ambient light settings: ambient.json (ya env AMBIENT_JSON path) se, warna Logic Looper wali default."""
    cfg = dict(AMBIENT_DEFAULT)
    p = os.getenv("AMBIENT_JSON", "ambient.json")
    try:
        if os.path.exists(p):
            with open(p, encoding="utf-8") as f:
                cfg.update(json.load(f))
    except Exception as e:
        logger.error(f"ambient json error: {e}")
    return cfg


def _px_fields(it: dict) -> dict:
    """rfp/xp = signed relative paths (always). rf/x absolute only if PROXY_BASE set.
    HTML player auto-detects base (CFG / same-origin) — user PROXY_BASE optional."""
    d: dict = {}
    page = str(it.get("page_url") or "")
    if page.startswith("http"):
        d["rfp"] = rf_path(page)
        if PROXY_BASE:
            d["rf"] = PROXY_BASE + d["rfp"]
    mode = (get_setting("proxy") or "auto").lower()
    u = it.get("download_link") or ""
    if mode == "off" or (it.get("type") or "VIDEO") in ("IMAGE", "PDF") or not str(u).startswith("http"):
        return d
    d["xp"] = px_path(u, page if page.startswith("http") else "")
    if PROXY_BASE:
        d["x"] = PROXY_BASE + d["xp"]
    if mode == "on" or px_needs(u, it.get("iplock") or ""):
        d["xa"] = 1
    return d


def _player_item(it: dict) -> dict:
    return dict({"t": it.get("title") or "Video", "u": it["download_link"], "k": it.get("type") or "VIDEO",
                 "p": it.get("page_url") or "", "th": it.get("thumb") or "", "d": it.get("duration") or 0,
                 "v": [[v["q"], v["u"]] for v in (it.get("variants") or [])],
                 "ip": it.get("iplock") or ""}, **_px_fields(it))



def _store_scrape(uid: int, results: List[dict], start: int, end: int, url: str, domain: str = ""):
    """Keep last results for Files pack button."""
    _LAST_SCRAPE[uid] = {
        "results": results,
        "start": start,
        "end": end,
        "url": url,
        "domain": domain or normalize_domain(url),
        "t": time.time(),
    }


def _build_scrape_files(results: List[dict], start: int, end: int, domain: str = "scrape"):
    """Return dict of text contents: full_txt, simple_txt, player_html, and tag."""
    tag = f"{domain}_p{start}_to_p{end}"
    full = f"--- {domain} | Pages {start}-{end} | {len(results)} Items ---\n\n"
    simple = f"--- {domain} Simple Links (Pages {start}-{end} | {len(results)} Items) ---\n\n"
    for i, it in enumerate(results, 1):
        full += (
            f"{i}. Title: {it.get('title') or 'Video'}\n"
            f"   Source Listing Page: {it.get('source_page') or ''}\n"
            f"   Permanent Video Page: {it.get('page_url') or ''}\n"
            f"   Direct Stream Link: {it.get('download_link') or ''}\n"
            + exp_line(it) + "\n"
        )
        simple += f"{it.get('title') or 'Video'}: {it.get('download_link') or ''}\n"
    player_html = generate_web_app_html(results, title=f"{domain} ({start}-{end})")
    return {
        "tag": tag,
        "full_txt": full,
        "simple_txt": simple,
        "player_html": player_html,
    }


async def send_files_pack(send_document, results: List[dict], start: int, end: int, domain: str = "scrape"):
    """Send: 2 TXT + 1 Player HTML + 1 ZIP (all together). Errors logged, partial send ok."""
    pack = await asyncio.to_thread(_build_scrape_files, results, start, end, domain)
    tag = pack["tag"]

    def mk(data: str, name: str):
        b = io.BytesIO(data.encode("utf-8"))
        b.name = name
        return b

    async def _one(name, data, caption):
        try:
            await send_document(document=mk(data, name), caption=caption)
            return True
        except Exception as e:
            logger.error(f"send_files_pack {name}: {e}")
            # ZIP-only fallback for this file
            try:
                zbuf = pack_result_zip(tag + "_" + name.replace(".", "_"), [(name, data)])
                if zbuf:
                    await send_document(document=zbuf, caption=caption + " (zip)")
                    return True
            except Exception as e2:
                logger.error(f"send_files_pack zip {name}: {e2}")
            return False

    await _one(f"{tag}_full.txt", pack["full_txt"], f"📁 Full TXT ({len(results)} links)")
    await _one(f"{tag}_simple.txt", pack["simple_txt"], f"📁 Simple TXT (Title: Stream)")
    await _one(f"{tag}_player.html", pack["player_html"], f"🌐 Full Web App HTML (Player UI)")
    try:
        zbuf = pack_result_zip(tag, [
            (f"{tag}_full.txt", pack["full_txt"]),
            (f"{tag}_simple.txt", pack["simple_txt"]),
            (f"{tag}_player.html", pack["player_html"]),
        ])
        if zbuf:
            await send_document(document=zbuf, caption=f"📦 ZIP — 2 TXT + 1 HTML ({len(results)} links)")
    except Exception as e:
        logger.warning(f"files pack zip fail: {e}")



