def generate_mascot_x_html(simple_txt: str, batch_name: str = "Stream Links",
                          username: str = None, password: str = None) -> str:
    """Mascotchlowa X HTML with Simple TXT auto-loaded.
    Default login stays permanent (html / 7989) unless username+password both provided.
    """
    tpl = _MASCOT_X_TEMPLATE
    # optional custom login — only if BOTH given
    if username and password:
        u_js = json.dumps(username)
        p_js = json.dumps(password)
        if "if(u==='html'&&p==='7989')" in tpl:
            tpl = tpl.replace(
                "if(u==='html'&&p==='7989')",
                f"if(u==={u_js}&&p==={p_js})",
                1,
            )
        elif "defaults:{user:'html',pass:'7989'" in tpl:
            tpl = tpl.replace(
                "defaults:{user:'html',pass:'7989'",
                "defaults:{user:" + u_js + ",pass:" + p_js,
                1,
            )
    body = (simple_txt or "").strip() or "# empty"
    seed = [{
        "id": "seed_auto",
        "name": (batch_name or "Simple Stream Links")[:80],
        "text": body,
        "thumb": "https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=900&q=80",
    }]
    seed_js = json.dumps(seed, ensure_ascii=False).replace("<", "\u003c").replace(">", "\u003e")
    old_init = "MX.sources=loadSources();updateLoginUI();renderBatches();"
    new_init = (
        "try{var __seed=" + seed_js + ";"
        "if(__seed&&__seed.length&&__seed[0].text){MX.sources=__seed;try{saveSources()}catch(_e){}}"
        "else{MX.sources=loadSources()||[]}}catch(e){MX.sources=loadSources()||[]}"
        "updateLoginUI();renderBatches();"
    )
    if old_init in tpl:
        tpl = tpl.replace(old_init, new_init, 1)
    else:
        logger.warning("mascot_x: init seed hook not found")
    return tpl



def _simple_txt_from_results(results: List[dict]) -> str:
    lines = []
    for it in results:
        t = (it.get("title") or "Video").replace("\n", " ").strip()
        u = (it.get("download_link") or "").strip()
        if u:
            lines.append(f"{t}: {u}")
    return "\n".join(lines) + ("\n" if lines else "")


def generate_web_app_html(results: List[dict], title: str = "Scraped Video Web Player", mini: bool = False) -> str:
    """Self-contained YouTube-style web player (password gate, auto thumbnails, favorites, history,
    HLS/MP4/WebM/MKV/DASH/TS/FLV/audio, external-player fallback)."""
    items = [_player_item(it) for it in results]

    def js(o) -> str:
        return (json.dumps(o, ensure_ascii=False).replace("</", "<\\/")
                .replace("\u2028", "\\u2028").replace("\u2029", "\\u2029"))

    cfg = {"title": title, "owner": BOT_OWNER_NAME, "tg": TELEGRAM_LINK, "amb": load_ambient_cfg(), "px": bool(PROXY_BASE),
           "pxBase": PROXY_BASE or "",
           "pxMode": (get_setting("proxy") or "auto"),
           "hash": hashlib.sha256(SKY_PASSWORD.encode("utf-8")).hexdigest() if SKY_PASSWORD else ""}
    if mini:
        cfg.update(mini=True, hash="")      # Mini App: login Telegram se hota hai, password nahi
    return (_PLAYER_TEMPLATE.replace("__OWNER__", _html.escape(BOT_OWNER_NAME))
            .replace("__TITLE__", _html.escape(title))
            .replace("__CFG__", js(cfg)).replace("__DATA__", js(items)))

